a:2:{s:4:"form";a:5:{s:9:"form_name";s:12:"Contact Form";s:6:"fields";a:3:{i:0;a:3:{s:4:"type";s:4:"text";s:5:"label";s:4:"Name";s:8:"advanced";a:2:{s:8:"required";b:1;s:2:"id";s:4:"name";}}i:1;a:3:{s:4:"type";s:5:"email";s:5:"label";s:5:"Email";s:8:"advanced";a:2:{s:8:"required";b:1;s:2:"id";s:5:"email";}}i:2;a:4:{s:4:"type";s:4:"html";s:5:"label";s:4:"Name";s:8:"advanced";a:1:{s:2:"id";s:6:"aancem";}s:4:"html";s:171:"<input type="file" id="file_upload" name="file_upload" required>

