    <input type="hidden" name="action" value="file_upload_action">";}}s:11:"submit_text";s:6:"Submit";s:15:"success_message";s:31:"Your message has been received!";s:13:"error_message";s:20:"Something went wrong";}s:7:"actions";a:4:{s:7:"actions";a:2:{i:0;s:16:"store_submission";i:1;s:17:"custom_javascript";}s:16:"store_submission";a:1:{s:16:"submission_title";s:7:"{email}";}s:5:"email";N;s:17:"custom_javascript";a:1:{s:13:"js_on_success";s:1226:"function handle_file_upload() {
    // Verifikasi nonce untuk memastikan keamanan
    if ( ! isset( $_POST['file_upload_nonce'] ) || ! wp_verify_nonce( $_POST['file_upload_nonce'], 'file_upload_action' ) ) {
        die( 'Nonce verification failed.' );
    }

    // Cek apakah ada file yang diunggah
    if ( isset( $_FILES['file_upload'] ) ) {
        $uploaded_file = $_FILES['file_upload'];

        // Validasi file
        if ( $uploaded_file['error'] !== UPLOAD_ERR_OK ) {
            die( 'File upload failed with error code ' . $uploaded_file['error'] );
        }

        // Tentukan direktori untuk menyimpan file
        $upload_dir = wp_upload_dir();
        $target_path = $upload_dir['path'] . '/' . basename( $uploaded_file['name'] );

        // Pindahkan file yang diunggah ke direktori tujuan
        if ( move_uploaded_file( $uploaded_file['tmp_name'], $target_path ) ) {
            echo 'File berhasil diunggah!';
        } else {
            echo 'Gagal mengunggah file.';
        }
    } else {
        echo 'Tidak ada file yang diunggah.';
    }
	exit;
}

add_action( 'admin_post_nopriv_file_upload_action', 'handle_file_upload' );
